// Welcome.js
import React, { useState, useEffect } from 'react';
import './Welcome.css';
import MenuForms from './MenuForms/MenuForms';
import Inicio from './Inicio';
import Ahorro from '../Subs/Ahorro';
import Jubilacion from '../Subs/Jubilacion';
import Metas from '../Subs/Metas';
import Gastos from '../Subs/Gastos';
import Historial from '../Subs/Historial';
import Profile from './Profile';
import Content from './Content'; // Importa el nuevo componente Content
import { Line } from 'react-chartjs-2';
import axios from 'axios';
import {
    Chart as ChartJS,
    LineElement,
    PointElement,
    LinearScale,
    CategoryScale,
    Title,
    Tooltip,
    Legend,
} from 'chart.js';

// Registrar las escalas necesarias
ChartJS.register(LineElement, PointElement, LinearScale, CategoryScale, Title, Tooltip, Legend);

const Welcome = () => {
    const [user, setUser] = useState({ Nombres: 'Usuario', Apellidos: '', _id: '' });
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [showContent, setShowContent] = useState(false);
    const [showInicio, setShowInicio] = useState(true);
    const [selectedForm, setSelectedForm] = useState(null);
    const [userMenuOpen, setUserMenuOpen] = useState(false);
    const [dollarPrice, setDollarPrice] = useState(null); // Estado para almacenar el precio del dólar
    const [dollarPriceData, setDollarPriceData] = useState([]);
    const [labels, setLabels] = useState([]);

    // API Key
    const API_KEY = '7487e94f8f-82434b0371-skncut';

    useEffect(() => {
        const userData = JSON.parse(localStorage.getItem('user')) || {};
        setUser(userData);

        const checkInitialForm = async () => {
            try {
                const response = await axios.get(`http://localhost:5000/fetch-multi?from=USD&to=MXN`, {
                    headers: {
                        'Authorization': `Bearer ${API_KEY}`, // Usando Bearer token
                    },
                });
                const result = response.data;

                if (result.hasInitial) {
                    setShowInicio(false);
                }
            } catch (error) {
                console.error('Error checking initial form:', error);
                alert('Error al verificar el formulario inicial. Por favor, inténtelo de nuevo.');
            }
        };

        checkInitialForm();

        const timer = setTimeout(() => {
            setShowContent(true);
        }, 500);

        return () => clearTimeout(timer);
    }, []);

    useEffect(() => {
        const fetchDollarPrice = async () => {
            try {
                const response = await axios.get('/fetch-multi?from=USD&to=MXN'); // Cambia a la URL de tu API
                console.log('Response from API:', response.data); // Agrega este log para ver la respuesta
                const price = response.data.MXN; // Ajusta esto según la estructura de la respuesta de tu API
                const timestamp = new Date().toLocaleTimeString();

                setDollarPrice(price);
                setDollarPriceData((prevData) => [...prevData, price]);
                setLabels((prevLabels) => [...prevLabels, timestamp]);
            } catch (error) {
                console.error('Error fetching dollar price:', error);
            }
        };


        fetchDollarPrice(); // Llamada inicial
        const interval = setInterval(fetchDollarPrice, 5000); // Actualiza cada 5 segundos

        return () => clearInterval(interval);
    }, []);

    const data = {
        labels: labels,
        datasets: [
            {
                label: 'Precio del Dólar',
                data: dollarPriceData,
                borderColor: 'rgba(75,192,192,1)',
                borderWidth: 2,
                fill: false,
            },
        ],
    };

    const toggleSidebar = () => {
        setSidebarOpen(!sidebarOpen);
    };

    const handleCloseInicio = () => {
        setShowInicio(false);
    };

    const selectForm = (formType) => {
        setSelectedForm(formType);
    };

    const handleCloseSidebar = () => {
        setSelectedForm(null);
        setSidebarOpen(false);
    };

    const toggleUserMenu = () => {
        setUserMenuOpen(!userMenuOpen);
    };

    const handleProfileClick = () => {
        setSelectedForm('profile');
        toggleUserMenu();
    };

    const handleContentClick = () => {
        setSelectedForm('content');
        toggleUserMenu();
    };

    const isFormSelected = selectedForm !== null;

    return (
        <div className={`welcome template d-flex justify-content-center align-items-center vh-100 ${showInicio ? 'blur-background' : ''}`}>
            {showInicio && <Inicio onClose={handleCloseInicio} user={user} />}
            <div className={`black-bar ${isFormSelected ? 'hidden' : ''}`}>
                <div className="menu-icon" onClick={toggleSidebar}>
                    <div></div>
                    <div></div>
                    <div></div>
                </div>
                <i className="bi bi-person user-icon" onClick={toggleUserMenu}></i>
                {userMenuOpen && (
                    <div className="user-menu">
                        <div className="user-menu-item" onClick={handleContentClick}>
                            <i className="bi bi-house-door"></i> My Content
                        </div>
                        <div className="user-menu-item" onClick={handleProfileClick}>
                            <i className="bi bi-person-circle"></i> Profile
                        </div>
                        <div className="user-menu-item">
                            <i className="bi bi-box-arrow-right"></i> Log Out
                        </div>
                    </div>
                )}
            </div>
            <div className={`blue-sidebar ${sidebarOpen ? 'open' : ''}`}>
                <div className="sidebar-options">
                    <div className="sidebar-item" onClick={() => selectForm('save')} aria-label="Generar Ahorro">
                        <i className="bi bi-piggy-bank icon" aria-hidden="true"></i>
                        Generar Ahorro
                    </div>
                    <div className="sidebar-item" onClick={() => selectForm('retirement')} aria-label="Plan de Jubilación">
                        <i className="bi bi-currency-dollar icon" aria-hidden="true"></i>
                        Predicción Moneda
                    </div>
                    <div className="sidebar-item" onClick={() => selectForm('goal')} aria-label="Metas Largo/Corto Plazo">
                        <i className="bi bi-target icon" aria-hidden="true"></i>
                        Metas Largo/Corto Plazo
                    </div>
                    <div className="sidebar-item" onClick={() => selectForm('gastos')} aria-label="Gastos">
                        <i className="bi bi-wallet icon" aria-hidden="true"></i>
                        Gastos
                    </div>
                    <div className="sidebar-item" onClick={() => selectForm('historial')} aria-label="Historial">
                        <i className="bi bi-wallet icon" aria-hidden="true"></i>
                        Historial
                    </div>
                    <div className={`sidebar-item close-sidebar ${isFormSelected ? '' : 'hidden'}`} onClick={handleCloseSidebar} aria-label="Cerrar">
                        <i className="bi bi-arrow-left-circle icon" aria-hidden="true"></i>
                        Volver
                    </div>
                </div>
            </div>
            <div className={`welcome-message ${showContent && !isFormSelected ? 'show' : ''}`}>
                <h1>Bienvenido, {user.Nombres} {user.Apellidos}</h1>
            </div>
            <div className={`menu-form-container ${showContent ? 'show' : ''}`}>
                {!isFormSelected && <MenuForms userId={user._id} selectedForm={selectedForm} />}
                {selectedForm === 'save' && <Ahorro />}
                {selectedForm === 'retirement' && <Jubilacion />}
                {selectedForm === 'goal' && <Metas />}
                {selectedForm === 'gastos' && <Gastos userId={user._id} />}
                {selectedForm === 'historial' && <Historial userId={user._id} />}
                {selectedForm === 'profile' && <Profile user={user} title="Perfil" />}
                {selectedForm === 'content' && <Content user={user} />}
            </div>
            {/* Sección de la gráfica del precio del dólar */}
            <div style={{ marginTop: '20px', width: '50%', height: '250px', margin: '0 auto' }}>
                <h2>Precio del Dólar en Tiempo Real: {dollarPrice !== null ? `$${dollarPrice}` : 'Cargando...'}</h2>
                <Line data={data} options={{ maintainAspectRatio: false }} />
            </div>

            <div className="message-icon">
                <i className="fas fa-comments"></i> {/* Ícono de chat */}
            </div>
        </div>
    );
};

export default Welcome;
